def min_minutes_to_palindrome(current_time):
    def is_palindrome(time_str):
        return time_str == time_str[::-1]

    hours, minutes = map(int, current_time.split(':'))
    current_time_int = hours * 100 + minutes

    while True:
        if is_palindrome(f"{current_time_int // 100:02}:{current_time_int % 100:02}"):
            break
        current_time_int += 1
        if current_time_int >= 2400:
            current_time_int = 0

    return current_time_int - current_time

# Example usage:
import sys
